import{_ as t,o as _,c as e,a3 as l}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/82-测一测你是否变成了“亲密敌人”.md","filePath":"books/attached/82-测一测你是否变成了“亲密敌人”.md","lastUpdated":1794298621000}'),p={name:"books/attached/82-测一测你是否变成了“亲密敌人”.md"};function i(o,a,r,s,d,n){return _(),e("div",null,[...a[0]||(a[0]=[l('<h3 id="测一测你是否变成了-亲密敌人" tabindex="-1">测一测你是否变成了“亲密敌人” <a class="header-anchor" href="#测一测你是否变成了-亲密敌人" aria-label="Permalink to &quot;测一测你是否变成了“亲密敌人”&quot;">​</a></h3><ul><li><p>你羞于向亲朋好友提及伴侣待你是多么恶劣。</p></li><li><p>当人们夸奖你伴侣的体贴、随和与细心时，你会感觉心中一惊。</p></li><li><p>你可能需要通过伴侣和别人的对话，来获悉他内心的真实想法。</p></li><li><p>遇到重要的事情，伴侣会优先和他人商议，而不是和你。</p></li><li><p>你都不确定在面临危险时，伴侣是否会抛却一切与你厮守。</p></li><li><p>相比于你，伴侣更注重自己在陌生人面前的形象。</p></li><li><p>看到朋友的恋人对他们体贴入微，你心里很不是滋味。</p></li><li><p>伴侣常常贬低或攻击你。</p></li><li><p>伴侣不那么在意你的身心健康。</p></li></ul><p>上面的条目是不是跟你的情况吻合呢？如果在关系中，你一直在热脸贴着冷屁股，要是你的伴侣对待陌生人都比对待你要好，对你的冷淡已成为常态，那么你就已然成了他的敌人。而你唯一的罪状就在于，太过接近而令他难以忍受。</p><p>而对于安全型人群来说，亲密关系圈内的生活就是截然不同的状况。</p>',4)])])}const m=t(p,[["render",i]]);export{h as __pageData,m as default};
